WordHunterWoW_QuestEN[97085] = { title = "Dangerous Enemies: Naigtal", description = "I hear your scouts talk of dangerous creatures and foes they have faced. \n\nIt makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here.\n\nI hope to see you return mostly intact.", objectives = "" }
WordHunterWoW_QuestEN[97086] = { title = "Dangerous Enemies: Naigtal (Heroic)", description = "I hear your scouts talk of dangerous creatures and foes they have faced. \n\nIt makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here.\n\nI hope to see you return mostly intact.", objectives = "" }
WordHunterWoW_QuestEN[97087] = { title = "More Disruption: Naigtal (Heroic)", description = "The stench of their forges still lingers. This means they are rebuilding. \n\nYou must keep at it if you hope to disrupt their operations enough to end their threat.\n\nNow you can go. Wreak havoc.", objectives = "" }
WordHunterWoW_QuestEN[97124] = { title = "Prey: Target 31 (Hard)", description = "", objectives = "" }
WordHunterWoW_QuestEN[97125] = { title = "Prey: Target 32 (Hard)", description = "", objectives = "" }
