WordHunterWoW_QuestEN[97213] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[97215] = { title = "A Secondary Strike", description = "We have struck a major blow against our enemies. Still, they continue their assaults.\n\nDecimus and my riftwardens have targeted another world from which they launch these attacks.\n\nThe bulk of our forces have temporarily withdrawn to the Voidstorm so that we may begin our assault on this second world.\n\nOur strike team awaits us at the Howling Ridge.", objectives = "" }
WordHunterWoW_QuestEN[97256] = { title = "Knocking Off the Top (Heroic)", description = "Even the most ruthless of creatures falter when they see their greatest champions crumble to ash.\n\nRemind our enemies here just how quickly their leaders fall!\n\nLet them know just how unrelenting and vicious you monsters of Azeroth really are! Bring me the Void Commander's Emblems and I will reward you accordingly.", objectives = "" }
WordHunterWoW_QuestEN[97321] = { title = "Slithering Spoils", description = "I've got good news and bad news.\n\nBad is that all those curios we dug up together? Melted.\n\nGood news? I've found some very interesting new poisons to work with.\n\nBut let me explain what happened...", objectives = "" }
WordHunterWoW_QuestEN[97381] = { title = "A Curated Gift", description = "I have watched the effort and care you take with the other mortals of your neighborhood, here in Founder's Point. This ceaseless labor on their behalf is the sort of behavior that I encourage. There's no profit to be had for you, but that isn't a driving concern for the best of your kind.\n\nIn recognition of your efforts and status, I offer you a gift. This small device contains a piece of decor for you to place in your home. I will have another for you next week.", objectives = "" }
WordHunterWoW_QuestEN[97382] = { title = "Counter-Curse Bounty", description = "Every part of dis isle is cursed, {name}. When de curse of Ula'tek coalesces into a fight, dat is when it is most important to strike back. We need all de help we can get keeping it at bay.\n\nYou look strong... but you'll need better equipment if you want to stay alive.\n\nDefeat the leader of one of dese surges, and then we can discuss a reward.", objectives = "" }
WordHunterWoW_QuestEN[97383] = { title = "Spirit Corrosion", description = "Our scouts found dis relic in one of da crypts. Maybe Er'inye knows what to do with it?", objectives = "" }
WordHunterWoW_QuestEN[97384] = { title = "More Spirit Corrosion", description = "One of those soulcoilers was carrying dis gem. You should show it to Er'inye.", objectives = "" }
WordHunterWoW_QuestEN[97454] = { title = "Seasonal Refresher: Midnight", description = "Since the opening of the Coiling Isles, things have started to get interesting again in delves.\n\nSee if our dear hosts have anything they can spare for those of us actually risking our necks and check the Delver's Guide for any updates.\n\nA quick refresher never hurt anyone.", objectives = "" }
WordHunterWoW_QuestEN[97455] = { title = "Call of the Bell", description = "<Years beneath the waves should have erased its details, yet the bell remains remarkably well-preserved. Whatever purpose it once served, the runes carved into it were clearly meant to endure.\n\nA sense of foreboding comes over you as you consider ringing it. Maybe not.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97457] = { title = "Fits Like a Glove", description = "<These appear to be a large pair of hand bones, that someone has hollowed out and claimed to be gauntlets.\n\nIt's a good thing you're already wearing gauntlets, or you'd be tempted to try them on.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97458] = { title = "Tackled and Boxed", description = "<An endless supply of fishing gear would be a dream for most anglers. The fact that this tacklebox screams whenever it is opened likely explains why it ended up at the bottom of the sea.\n\nAfter spending enough time with it, the screams start to echo without needing to open it at all.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97459] = { title = "Something Smelly", description = "<The inscription promises to not only attract spirits, but to whip them into a violent frenzy if enough is burned. That can't end well.\n\nStill, it does smell nice.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97460] = { title = "Lightly Salted", description = "<The pouch is unremarkable, but its history may not be. Ritual salts have long been used to call upon ancestors, spirits, and powers beyond the mortal world.\n\nThis salt is extra-salty, having been in the ocean. Perhaps that makes it extra-potent?\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97461] = { title = "Cursed Fishing 101", description = "<Most fishing manuals concern themselves with bait, weather, and patience. This weathered tome boasts lessons on hexing one's fishing rivals and communing with the deep.\n\nYou sense you are wading into dangerous waters.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97462] = { title = "Rocky Shores", description = "<This faceted ore hums with an unsettling energy. Whether it is valued more for its practical uses or its strange properties, you cannot say.\n\nYou feel compelled to lick it, though you know you shouldn't.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97463] = { title = "Just a Normal Knife", description = "<This blade shows no signs of battle wear, only careful maintenance. Its purpose was clearly ceremonial, but for what ceremony?\n\nThe red gleam to the metal gives you a clue.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97464] = { title = "A Dash of Poison", description = "<The glass is thick and reinforced, suggesting the contents were considered dangerous--or valuable. The verdant liquid within glimmers as it shifts in the vial.\n\nYou think you smell something acrid and noxious about it. But it could be that this whole isle smells acrid and noxious.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97465] = { title = "The Intended Way to Fish", description = "<It's a spear. The fishing rod is a spear.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97482] = { title = "Fangs for the Memories", description = "That snake monstrosity was vicious, with venom potent enough to burn through stone.\n\nWe'll want to make sure we get our hands on the best gear we can before we think about taking it on.\n\nI've got some ideas about turning that venom to our own ends, though, so we can hit the ground running.", objectives = "" }
WordHunterWoW_QuestEN[97491] = { title = "<DNT> Early Scenario Steps Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[97492] = { title = "<DNT> Early Scenario Steps Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[97521] = { title = "A Turtle Bade It to the Water", description = "Greetings, settler!\n\nThere's a cove off the coast that my people have turned into a tavern. It's open year round, but we like to help drum up some business for them whenever we come to town. Would you care to help?", objectives = "" }
WordHunterWoW_QuestEN[97535] = { title = "A Bargain You Won't Refuse", description = "<A voice hisses in your mind.>\n\nAm I to be another victim in your pointless conquest? I wonder... will you skin me alive and boil me in a stew? Or simply leave me to rot on a pile of your forgotten excess?\n\nWhat if I can offer you something... better? Something... delicious. The Children of Ula'tek are a blight on this world. On this we agree. Bring me proof of their demise.", objectives = "" }
WordHunterWoW_QuestEN[97557] = { title = "Tailing the Tlhapi", description = "Toxic Tlhapi. Nasty little fish.\n\nEverything's wrong about them, from their big, buggy eyes to their sweet, succulent meat...\n\n<Gills clears their throat.>\n\nNot to mention the toxicity. The seas would be much better without them fouling things up.", objectives = "" }
WordHunterWoW_QuestEN[97559] = { title = "The Familiar Taste of Poison", description = "Surely by now even you understand the threat Ula'tek poses, yes? Her wretched power oozes forth time and time again.\n\nIf I am to do my part, I will need proof of your devotion to our... agreement, shall we call it? When next her acolytes call forth their twisted mongrels, slay them and collect their remains.", objectives = "" }
WordHunterWoW_QuestEN[97562] = { title = "Culling the Killifish", description = "Spotted Killifish. Grotesque little creatures.\n\nThe little demons swarm like insects, washing up on shores in such horrific numbers that it would take several meals to devour them all.\n\n<Gills' belly burbles audibly.>\n\nYou can do your part by collecting some for me, ridding the waters of their foul presence.", objectives = "" }
WordHunterWoW_QuestEN[97565] = { title = "Tipping the Scaled", description = "<The wretched things you gathered briefly wink out of existence, returning in the same breath as one object.>\n\nGo on, take it. Carry it to the Vaults of Atal'Utek. Affix it to that dismal rod of yours and cast it into the fetid pools to draw out one of Ula'tek's pets. You do have the skill to fish anywhere, don't you?", objectives = "" }
WordHunterWoW_QuestEN[97571] = { title = "Dogging the Darters", description = "Dirty Darters. Ghoulish little buggers.\n\nThe way they flit about the water is so unnerving, so disquieting, one can't help but imagine them darting right down one's gullet...\n\n<Gills coughs rather loudly>\n\nYou can do your part by collecting some for me, ridding the waters of their foul presence.", objectives = "" }
WordHunterWoW_QuestEN[97616] = { title = "Corrosive Gifts: Corrosive Power", description = "<You feel a change in the air as you take this ancient volume into your hands.\n\nThough it prickles and burns your skin, your mind radiates with thoughts of the power it contains and the peril it represents.\n\nYou must know more.\n\nThere is only one place on the isle profane enough for this tome. In your mind's eye, you glimpse the Altar of Corrosion.>", objectives = "" }
WordHunterWoW_QuestEN[97621] = { title = "The Singularity Anchor", description = "Our sojourn to this world has brought the ren'dorei an even deeper understanding of the Void than before. The domanaar with whom we share a common enemy are almost strangely generous with their knowledge. I believe they want us to become as fearsome as they are.\n\nThere is a Singularity Anchor in Stormarion Citadel. I have learned how to draw upon some of its power to craft you a powerful item.\n\nBut first, we must ensure it does not fall into the hands of our enemies.", objectives = "" }
WordHunterWoW_QuestEN[97622] = { title = "A Soiree to Remember", description = "You seek an audience with Saltheril? And you're wearing... that? Excuse me for a moment while I laugh into my handkerchief.\n\n<Caeris laughs lightly behind his handkerchief.>\n\nNow, let me be professional. You are cordially invited to attend Saltheril's soiree.\n\nDon't embarrass yourself, {name}. The best of Silvermoon are watching.", objectives = "" }
WordHunterWoW_QuestEN[97624] = { title = "Seeking Legends", description = "Harandar hides wisdom in every annal of its history, {name}. You would do well to seek out its legends for yourself. I suspect you may learn something of this world and our places in it.", objectives = "" }
WordHunterWoW_QuestEN[97625] = { title = "Glorious Abundance", description = "De Loa of Abundance may not be one of de four great ones, but his worshippers are certainly de most devout.\n\nSeek him out yaself. You can find him in northern Zul'Aman near Halazzi's Temple, but I also hear he's established harvest sites in Eversong Woods, Harandar, and even de land of Void through de gargantuan skymouth.\n\nIf nothing else, de rewards he grants are glorious--to de worthy, at least.", objectives = "" }
WordHunterWoW_QuestEN[97640] = { title = "Vaults of Atal'Utek: One Coin Too Many", description = "You don't look so good, {name}.\n\n<As Abdumati examines you grimly, your heart starts pounding and your vision goes green. The weight of the coin in your pocket feels overwhelming.>\n\nYou found something out dere, huh? De vaults are full of treasure, most of it cursed.\n\nI don't trust her, but dat spirit-witch you saw knows all de secrets of dis horrid place. If anyone can help, it's her.", objectives = "" }
WordHunterWoW_QuestEN[97661] = { title = "The Protection of the Med'jai", description = "<This amulet feels warm and smooth in your hand.\n\nAs you hold it, you feel relief from the weight of your corrosion, as if the amulet offers some protection from Ula'tek's curse.\n\nEr'inye would likely be interested in studying it.>", objectives = "" }
WordHunterWoW_QuestEN[97662] = { title = "The Winds of Tok'jara", description = "<As your hand closes around this fragile feather, a spectral wind echoes through the vaults.\n\nWith it, you feel the weight of your spirit's corrosion lift, as if you could simply spread your wings and fly out of this cursed place.\n\nYou can't, of course. But Er'inye might be interested in studying it.>", objectives = "" }
WordHunterWoW_QuestEN[97668] = { title = "The Watchful Gaze of Szarith", description = "<Clutching the serpentine eyeball, you feel a new awareness creeping up the back of your neck.\n\nThe Eggs of Ula'tek. By the hundreds. You can sense their every twitching presence, waiting to burst into vile venom and more of her wretched spawn.\n\nYou wish you could toss it into the deepest crypt, but its power is undeniably potent. Er'inye would be interested in studying it.>", objectives = "" }
WordHunterWoW_QuestEN[97669] = { title = "The Luck of the Bound Spirit", description = "<You hold a simple lynx's paw, worn by time and worry, that the spirit left as a parting gift.\n\nThough it holds no magical properties of its own, it is swollen with the hopes and fears of every bound spirit that crossed its path in this miserable place.\n\nThe result is quite potent, if emotionally harrowing. Er'inye would likely be interested in studying it.>", objectives = "" }
WordHunterWoW_QuestEN[97670] = { title = "A Handful of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[97672] = { title = "A Cluster of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[97673] = { title = "A Trove of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[97910] = { title = "Cracked Keystone", description = "Fragmentary images of heroic deeds flash through your mind as you touch the stone, but they fade as fast as they arrive.\n\nPerhaps performing a suitably impressive task will stabilize the stone's magic once more?", objectives = "" }
WordHunterWoW_QuestEN[97945] = { title = "In the Catalyst's Shadow", description = "Ah, {name}! Good. Now that you've helped me amass such a wealth of resources, it's time for me to pursue other... interests.\n\nWhat? You expected a more dramatic betrayal? Never!\n\nDon't worry, {name}, while I may be occupied elsewhere, I'll never tire of watching your adventures.\n\nAdventures still bolstered by my gifts, of course. Many have shown interest, but I've only found one void elf... amusingly strange enough to mentor.\n\nOrin Straylight is the name. You'll find him by the Catalyst in Silvermoon.", objectives = "" }
WordHunterWoW_QuestEN[97978] = { title = "Prismatic Potential", description = "Greetings, {class}. Our mutual friend explained everything to us. Don't worry, my shade and I took to Decimus' voidweaving like fish to water.\n\nWe had an idea. The Catalyst's transformative energies are immense and span the breadth of known elemental forces.\n\nIf I can learn to isolate the void from that spectrum of power, I could use it to weave Nebulous Voidcores just as Decimus did with the Voidforge.\n\nWe are no domanaar, though. We need practice.", objectives = "" }
WordHunterWoW_QuestEN[97981] = { title = "Umbral Blessings of the Catalyst", description = "I'm glad you're here, {name}. I've worked it all out! I can filter the Catalyst's energies through a void prism to isolate the bands necessary to weaving Nebulous Voidcores.", objectives = "" }
WordHunterWoW_QuestEN[98012] = { title = "Nebulous Voidcores: Veteran Mistcrest", description = "I can prepare another Nebulous Voidcore for you using the Catalyst, but we'll need raw materials to fuel the process.\n\nThose crests you use to empower equipment have a certain latent energy that reacts in just the right way when exposed to the Catalyst.", objectives = "" }
WordHunterWoW_QuestEN[98015] = { title = "Nebulous Voidcores: Voidlight Marl", description = "I can prepare another Nebulous Voidcore for you using the Catalyst, but we'll need raw materials to fuel the process.\n\nVoidlight Marl is an ideal reagent for this purpose. Its prismatic properties greatly simplify the process of isolating void energy from the chaotic power of the Catalyst.", objectives = "" }
WordHunterWoW_QuestEN[98016] = { title = "Nebulous Voidcores: Gold", description = "I can weave another Nebulous Voidcore for you out of the accumulated power of the Catalyst, but we'll need raw materials to fuel the process.\n\nI have found a way to repurpose the conductive properties of gold for this transformation. It isn't cheap, but it works.", objectives = "" }
WordHunterWoW_QuestEN[98172] = { title = "Trailing Xal'atath", description = "We must not lose sight of our true goal here in Silvermoon, {name}: to bring Xal'atath to justice.\n\nWe all saw her void armies at the Sunwell. They were rushing downward, INTO the well, a thousand a minute. And now: silence.\n\nListen for their whispers, {class}. With any luck, we'll pick up on their trail again, and then we'll find Xal'atath... and perhaps even those that pursued her.", objectives = "" }
WordHunterWoW_QuestEN[98204] = { title = "Cursed Keepsake", description = "<A containment shield hums, wrapping tightly about the keepsake. The object projects an aura of sorrow and suffering.\n\nAccording to the Last Architect, this keepsake is cursed, but it can be cleansed. One must simply fold their essence inside that of the object and remove the corruption from within. How dangerous could it be?>", objectives = "" }
WordHunterWoW_QuestEN[98213] = { title = "Midnight (90) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[98218] = { title = "Return to Amani'Zar", description = "{name},\n\nYour aid is requested in Amani'Zar Village. Please meet me there.\n\n--Liadrin", objectives = "" }
WordHunterWoW_QuestEN[98220] = { title = "Altar of Fangs", description = "The Children of Ula'tek writhe at the heart of her temple, mutating into more and more wretched versions of themselves. If left unchecked, they'll soon become venomous monstrosities we have no hope of fighting.\n\nI hate to send you into a den of vipers, {name}, but we have no other choice. Get in there and thin out the swarm, before those vile serpents devour the world.", objectives = "" }
WordHunterWoW_QuestEN[98226] = { title = "The Venomous Abyss: Deception Unmasked", description = "If my brother is no longer bowing to Malacrass, then he's in grave danger. We need to find a way to get to dem as quickly as possible. Look for anything that could let us get through de temple faster.", objectives = "" }
WordHunterWoW_QuestEN[98228] = { title = "The Venomous Abyss: Deception Unmasked", description = "If my brother is no longer bowing to Malacrass, then he's in grave danger. We need to find a way to get to dem as quickly as possible. Look for anything that could let us get through de temple faster.", objectives = "" }
WordHunterWoW_QuestEN[98229] = { title = "The Venomous Abyss: Deception Unmasked", description = "If my brother is no longer bowing to Malacrass, then he's in grave danger. We need to find a way to get to dem as quickly as possible. Look for anything that could let us get through de temple faster.", objectives = "" }
WordHunterWoW_QuestEN[98232] = { title = "Midnight: Vaults of Atal'Utek", description = "Zul'jarra's forces stand watch at the gates of the Vaults of Atal'Utek, holding the line against those wicked serpents.\n\nThe fate of the entire Eastern Kingdoms rests on their blades. We would do well to provide them with reinforcements. The Children of Ula'tek are fierce, but they are no match for a seasoned {class} like you.\n\nTraverse the temple and thin their ranks, however you can.", objectives = "" }
WordHunterWoW_QuestEN[98234] = { title = "Week 1 of 3: Gladiator's Distinction", description = "Interested in training against some of our fighters? Step into the ring and show us your mettle.\n\nMake sure you equip these medallions, and defeat at least two teams of enemies.", objectives = "" }
WordHunterWoW_QuestEN[98295] = { title = "Week 2 of 3: Crowd Control", description = "Good work using your Gladiator's Distinction bonus. Now I want you to try defeating some enemy teams after landing a crowd control effect!", objectives = "" }
WordHunterWoW_QuestEN[98311] = { title = "Week 3 of 3: Interrupts and Dispels", description = "I have one final lesson for you. Get in there and interrupt an enemy spell cast, or dispel a harmful effect from yourself or an ally. Then, defeat your enemy two more times.", objectives = "" }
WordHunterWoW_QuestEN[98343] = { title = "Venom Fishing: My Second-Best", description = "Before I send ye out hunting, ye should acquaint yerself with what remains of my crew.\n\nMost perished in the wreck, of course. Others fell into the swamp. Some traitorous gits... well, we'll get to them in a moment, won't we?\n\nBut me loyal second mate is holding down the fort, just down river of me Landing. She'll set you up right.", objectives = "" }
WordHunterWoW_QuestEN[98388] = { title = "Into the Vaults of Atal'Utek", description = "Past dis bulwark, there's nothin but snakes, spirits, and venomous death.\n\nI've lost three lieutenants dis week. Strong ones. Brave ones. Maybe stronger and braver than you.\n\n<Warleader Abdumati looks you over with a weary eye.>\n\nIf you want to fling yaself into de abyss, be my guest. Bring back my scouts, if you can find dem amongst de bones.\n\nBut watch your step. Dat venom will swallow you whole.", objectives = "" }
WordHunterWoW_QuestEN[98406] = { title = "A Curated Gift", description = "I have watched the effort and care you take with the other mortals of your neighborhood, here in Razorwind Shores. This ceaseless labor on their behalf is the sort of behavior that I encourage. There's no profit to be had for you, but that isn't a driving concern for the best of your kind.\n\nIn recognition of your efforts and status, I offer you a gift. This small device contains a piece of decor for you to place in your home. I will have another for you next week.", objectives = "" }
WordHunterWoW_QuestEN[98414] = { title = "A Request from the Captain", description = "Oh, uh. The Captain has requested you join him at Tokka's Landing as soon as you can.\n\n<Second Mate Sluggs quivers in her shell.>\n\nHe had a mean look about him. Tread lightly.", objectives = "" }
WordHunterWoW_QuestEN[98415] = { title = "A Favor to the Captain", description = "Oh! While you were out fishing, Captain Tokka asked to see you again. I think he's beginning to trust you.\n\n<Second Mate Sluggs grimaces.>\n\nThe Captain's trust d-does tend to come with caveats.", objectives = "" }
WordHunterWoW_QuestEN[98416] = { title = "A Plea from the Captain", description = "Ohh, the Captain's really in a foul mood this time. I think you'd better go see what he wants.\n\n<Second Mate Sluggs shakes her head.>\n\nYou're the only one who can soothe his storms, these days.", objectives = "" }
WordHunterWoW_QuestEN[98419] = { title = "Shoulder to Shoulder", description = "De Vaults are a dangerous place. Lotta brave, headstrong fighters think dey can face de Children of Ula'tek alone. If dey're lucky, we manage to recover de bodies before dey get eaten.\n\nI like you, {name}. It'd be a shame to see a serpent feed you to its young. So be smart. Find people to watch your back, then carve your way through de temple together.", objectives = "" }
WordHunterWoW_QuestEN[98420] = { title = "What's Out There?", description = "Knowledge is de most important weapon in war. These Vaults are ancient and vast--our scouts cannot see everything. What lurks in de depths of these corrupted halls?\n\nDat's precisely what I need to know. Get out there and tell me what you see, but it's dangerous to go alone. You best bring some comrades if you want to make it back.", objectives = "" }
WordHunterWoW_QuestEN[98428] = { title = "Vaults of Atal'Utek: The Altar of Corrosion", description = "De Altar of Corrosion.\n\nWho can say when dis accursed piece of stone rose out of de venom? I have studied it for lifetimes and have only just tasted its power.\n\n<Er'inye licks her spectral lips.>\n\nSay de word, and I will convert de corrosion you carry to something more useful. Den, you may commune with de Altar and accept its many gifts.", objectives = "" }
WordHunterWoW_QuestEN[98515] = { title = "Vaults of Atal'Utek: A Toxic Tour", description = "Dis temple is where all de Children of Ula'tek first crawl out of de ooze. Dis is where we hold de line.\n\nDe threat comes in waves. Sometimes short strikes. Sometimes an incursion dat overwhelms de whole temple. Sometimes a huge monstrosity rising out of de venom.\n\nWhatever dey send, send it back cryin' to its big evil mama!\n\nAnd in de meantime, do what you can to keep our patrols safe.", objectives = "" }
